def transform_message(message):
    def toggle_case(char):
        return char.swapcase()

    def shift_vowels(char):
        vowels = "aeiouAEIOU"
        if char in vowels:
            return chr(ord(char) + 2)
        return char

    return "".join(shift_vowels(toggle_case(c)) for c in message)

def count_positive_digit_sum(arr):
    """Counts numbers in the array that have a positive digit sum."""
    def digit_sum(n):
        """Calculate the sum of digits of a number."""
        return sum(int(d) for d in str(abs(n)))

    return sum(1 for num in arr if digit_sum(num) > 0)

def check(x, y, z):
    if not all(isinstance(v, int) for v in (x, y, z)):
        return False
    return x == y + z or y == x + z or z == x + y

def double_difference_of_odd_positives(numbers):
    odd_positives = [num for num in numbers if num > 0 and num % 2 != 0]
    if not odd_positives:
        return 0
    difference = max(odd_positives) - min(odd_positives)
    return 2 * difference

import re
import sys

def transform(text: str) -> str:
    text = re.sub(r' {3,}', '-', text)
    return text.replace(' ', '_')

def digits(n: int) -> int:
    """Return the number of digits of an integer, ignoring a leading minus sign."""
    return len(str(abs(n)))

def sum_first_k_at_most_two_digits(arr: list[int], k: int) -> int:
    """
    Sum the first k elements of arr that have at most 2 digits.
    """
    filtered = filter(lambda x: digits(x) <= 2, arr)
    total = 0
    count = 0
    for num in filtered:
        if count >= k:
            break
        total += num
        count += 1
    return total

